mapper.select:
SELECT s.*, u.USER_NAME as SELLER_NAME, pi.IMAGE_URL as IMAGE_URL FROM sales s LEFT JOIN users u ON s.SELLER_ID = u.ID LEFT JOIN product_images pi ON s.SALE_ITEM_ID = pi.PRODUCT_ID AND pi.PRODUCT_TYPE = 'sale' AND pi.IS_THUMBNAIL = 'y' WHERE 1=1
AND s.SELLER_ID = #{sellerId}
AND s.TITLE LIKE '%' || #{productName} || '%'
AND s.JUDGE_KIND_NAME = #{productType}
ORDER BY s.CREATED_TIME DESC

SELECT IMAGE_URL
FROM product_images
WHERE PRODUCT_ID = #{productId}
AND PRODUCT_TYPE = #{productType}
ORDER BY ORDER_INDEX
